// Verifies a call from CommerceOS (FX-55, ADR-110; n8n/deployment/import.md):
//   X-CommerceOS-Timestamp: unix seconds (at most 5 minutes old)
//   X-CommerceOS-Signature: v1=<hex HMAC-SHA256(COMMERCEOS_N8N_WEBHOOK_SECRET, "<timestamp>.<raw body>")>
// Needs COMMERCEOS_N8N_WEBHOOK_SECRET, N8N_BLOCK_ENV_ACCESS_IN_NODE=false and NODE_FUNCTION_ALLOW_BUILTIN=crypto in
// the n8n environment, and Raw Body on the trigger. The body used downstream is the one that was signed.
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const secret = $env.COMMERCEOS_N8N_WEBHOOK_SECRET;
let reason = null;
let raw = null;
if (!secret) reason = 'n8n is not configured with COMMERCEOS_N8N_WEBHOOK_SECRET';
else if (!item.binary || !item.binary.data) reason = 'no raw body (enable Raw Body on the trigger)';
else raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const ts = String(headers['x-commerceos-timestamp'] || '');
const given = String(headers['x-commerceos-signature'] || '');
if (!reason && !/^\d{9,11}$/.test(ts)) reason = 'missing or malformed timestamp';
if (!reason && Math.abs(Date.now() / 1000 - Number(ts)) > 300) reason = 'timestamp too old or in the future';
if (!reason) {
  const expected = 'v1=' + crypto.createHmac('sha256', secret).update(ts + '.' + raw).digest('hex');
  const a = Buffer.from(given);
  const b = Buffer.from(expected);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) reason = 'signature does not match';
}
let body = null;
if (!reason) {
  try {
    body = JSON.parse(raw);
  } catch (e) {
    reason = 'body is not JSON';
  }
}
return [{ json: { headers, body, signature_verified: !reason, signature_error: reason } }];

// Extract checkout session and consent details
const input = $input.first().json;
const event = input.event || input.body || input;
const payload = event.payload || {};

const customerPhone = payload.customer_phone || payload.phone;
const checkoutId = payload.checkout_id || event.aggregate_id;
const cartValue = Number(payload.subtotal || 0);

if (!customerPhone) {
  throw new Error('VALIDATION_ERROR: Missing customer_phone for abandoned checkout recovery');
}

return [{
  json: {
    tenant_id: event.tenant_id,
    checkout_id: checkoutId,
    customer_phone: customerPhone,
    cart_value: cartValue,
    correlation_id: `recov_${checkoutId}`,
    idempotency_key: `idemp_cart_recov_${checkoutId}`,
    notification_payload: {
      channel: 'WhatsApp',
      recipient: customerPhone,
      template_code: 'ABANDONED_CART_RECOVERY',
      body: `You left items in your cart! Complete your order now and enjoy special free delivery.`,
      order_id: checkoutId
    }
  }
}];
